  /* ===================== Állítások (ISA 315, 2019) és eljárások ===================== */
  var allitasTerms = [
    { id: 'allitasok-rendszere', term: 'Állítások rendszere az ISA 315 szerint', en: 'assertions under ISA 315 (Revised 2019)', topic: 'allitas',
      short: 'A vezetés a beszámolóval kimondva vagy hallgatólagosan állításokat tesz az elszámolásról, értékelésről és bemutatásról. Az ISA 315 (2019) két csoportot különít el: az időszak ügyleteire és eseményeire, valamint a fordulónapi számlaegyenlegekre vonatkozó állításokat – a bemutatás mindkettőnek része.',
      prereq: ['konyvvizsgalat/allitasok'],
      text: '**Ügyletek, események és kapcsolódó közzétételek (az időszakra):**\n\n- **bekövetkezés** (megtörténtség, occurrence) – a rögzített ügylet megtörtént és a gazdálkodóhoz tartozik;\n- **teljesség** (completeness) – minden ügyletet rögzítettek;\n- **pontosság** (accuracy) – az összegek és adatok helyesek;\n- **időbeli elhatárolás** (cut-off, időszakhoz rendelés) – a helyes időszakba kerültek;\n- **besorolás** (classification) – a megfelelő számlákon;\n- **bemutatás** (presentation) – megfelelően összevonva/bontva, érthetően leírva, a közzétételek relevánsak.\n\n**Számlaegyenlegek és kapcsolódó közzétételek (a fordulónapra):**\n\n- **létezés** (existence);\n- **jogok és kötelezettségek** (rights and obligations);\n- **teljesség**;\n- **pontosság, értékelés és felosztás** (accuracy, valuation and allocation);\n- **besorolás**;\n- **bemutatás**.\n\nA 2019-es átdolgozás a korábbi harmadik csoportot (bemutatás és közzététel) beolvasztotta: a közzétételek a kapcsolódó ügyletekhez és egyenlegekhez tartoznak. A könyvvizsgáló más csoportosítást is használhat, ha az minden szempontot lefed.\n\n**Releváns állítás**: amelyhez azonosított lényeges hibás állítás kockázat tartozik. Az eljárásokat mindig ezekhez tervezzük.\n\n**Irány-szabály**: a túlértékelés kockázata (eszköz, bevétel) → bekövetkezés/létezés → a könyvekből indulunk; az alulértékelés kockázata (kötelezettség, ráfordítás) → teljesség → a könyveken kívüli forrásból indulunk.',
      example: 'Vevőkövetelés 120 M Ft: **létezés** – megerősítő levél; **jogok** – nincs-e faktorálva/engedményezve (szerződések, banki megerősítés); **értékelés** – korosítás, utólagos befolyások, értékvesztés; **időbeli elhatárolás** – a fordulónap körüli szállítólevelek; **bemutatás** – a zálogjog közzététele.',
      pitfall: 'Az állítások nem egyformán fontosak minden tételnél: eszközöknél és bevételeknél jellemzően a létezés/bekövetkezés, kötelezettségeknél és ráfordításoknál a teljesség a kritikus – mert a vezetés ösztönzője általában az eredmény és a vagyon „szépítése”.',
      related: ['isa-315', 'isa-500', 'letezes', 'bekovetkezes', 'teljesseg', 'pontossag-ertekeles', 'idobeli-elhatarolas', 'besorolas', 'bemutatas', 'jogok-kotelezettsegek', 'eljaras-allitas-matrix'],
      widget: { type: 'audit-allitas' } },

    { id: 'bekovetkezes', term: 'Bekövetkezés (megtörténtség)', en: 'occurrence', topic: 'allitas',
      short: 'Az időszakban rögzített ügyletek és események valóban megtörténtek, és a gazdálkodóhoz tartoznak. A fiktív árbevétel és a nem létező beszerzés ellen véd – a túlértékelés kockázatára válaszol.',
      text: '**Tipikus kockázat**: fiktív vagy duplikált értékesítés, „papíron” teljesített szolgáltatás, kapcsolt félnek visszavételi joggal leszállított áru, nem a céget érintő kifizetés (magánkiadás).\n\n**Eljárás iránya**: a **könyvelésből** (árbevétel-főkönyv, értékesítési napló) választunk mintát, és visszakeressük a forrásig (vevői megrendelés, aláírt szállítólevél, befolyt ellenérték) – ez a **vouching**.\n\n**Erős bizonyíték**: a vevő által aláírt átvételi igazolás, a független fuvarozói dokumentum, a pénz befolyása a bankszámlára. **Gyenge**: a cég saját számlamásolata (azt ő állította ki).',
      example: 'Az árbevétel-főkönyvből 30 decemberi számlát választanak; mindegyikhez megkeresik a vevő által aláírt CMR-t és a januári befolyást. Két számlánál nincs szállítólevél, és a vevő januárban jóváírást kapott – fiktív bevétel gyanúja.',
      pitfall: 'A szállítólevélből kiinduló minta nem a bekövetkezést, hanem a teljességet teszteli. A bekövetkezésnél a kiinduló halmaz a könyvelt tételek köre.',
      related: ['allitasok-rendszere', 'letezes', 'teljesseg', 'vouching-tracing', 'arbevetel-vizsgalata', 'isa-240'] },

    { id: 'letezes', term: 'Létezés', en: 'existence', topic: 'allitas',
      short: 'A mérlegben kimutatott eszközök, kötelezettségek és saját tőke elemek a fordulónapon léteznek. Elsősorban az eszközök túlértékelése ellen véd.',
      text: '**Tipikus eljárások**:\n\n- **fizikai szemle** (tárgyi eszköz, készlet – a nyilvántartásból a fizikai tételig);\n- **külső megerősítés** (bank, vevő, letétkezelő);\n- leltár megfigyelése, próbaszámlálás a listáról a polcra;\n- nyilvántartások (pl. ingatlan-nyilvántartás, gépjármű-forgalmi engedély) szemléje.\n\nA létezés **egyenlegállítás** (fordulónapi kép), szemben a bekövetkezéssel, amely az időszak ügyleteire vonatkozik.',
      example: 'A tárgyieszköz-nyilvántartásból kiválasztott 15 gépet a könyvvizsgáló a gyártócsarnokban személyesen azonosítja (gyári szám, leltári címke). Egy gépet tavaly selejteztek, de nem vezették ki: létezési hiba.',
      pitfall: 'A létező eszköz még nem biztosan a cégé (jogok és kötelezettségek), és nem biztos, hogy a könyv szerinti értéken (értékelés). A bérelt, bizományba kapott vagy idegen készlet létezik a raktárban, de nem a cég eszköze.',
      related: ['allitasok-rendszere', 'bekovetkezes', 'jogok-kotelezettsegek', 'vouching-tracing', 'isa-501', 'isa-505', 'targyi-eszkozok-vizsgalata'] },

    { id: 'teljesseg', term: 'Teljesség', en: 'completeness', topic: 'allitas',
      short: 'Minden ügyletet, eseményt, eszközt, kötelezettséget és közzétételt rögzítettek, aminek szerepelnie kellett. A kötelezettségek és ráfordítások alulértékelése ellen véd – ehhez a könyveken kívüli forrásból kell kiindulni.',
      text: '**Tipikus kockázat**: el nem számolt szállítói számlák, hiányzó céltartalék, ki nem mutatott garancia- vagy perköltség, elmaradt közzététel, nem könyvelt árbevétel (adóelkerülés esetén).\n\n**Eljárás iránya**: a **forrásból** (szállítólevél, beérkezett számla, januári kifizetés, szerződés) indulunk, és megnézzük, szerepel-e a könyvekben – ez a **tracing**.\n\n**Tipikus eljárások**:\n\n- **el nem számolt kötelezettségek keresése**: a fordulónap utáni kifizetések és beérkezett számlák vizsgálata;\n- szállítói egyenlegközlők a nulla vagy kis egyenlegű, de nagy forgalmú szállítóknál is;\n- jegyzőkönyvek, szerződések, ügyvédi levelek átnézése (céltartalék, függő kötelezettség);\n- elemző eljárás (pl. hiányzó havi rezsiköltség).',
      example: 'A könyvvizsgáló a január 1–február 15. közötti összes 1 M Ft feletti kifizetést átnézi, és megvizsgálja, melyik vonatkozik decemberi teljesítésre. Egy 8 M Ft-os decemberi javítási számla nincs a szállítók között: teljességi hiba.',
      pitfall: 'A szállítói egyenlegközlőt nem csak a nagy egyenlegű szállítóknak kell küldeni: a teljesség szempontjából épp a **nagy forgalmú, de kis egyenlegű** szállító a gyanús.',
      related: ['allitasok-rendszere', 'bekovetkezes', 'vouching-tracing', 'szallitok-vizsgalata', 'idobeli-elhatarolas'] },

    { id: 'pontossag-ertekeles', term: 'Pontosság, értékelés és felosztás', en: 'accuracy; accuracy, valuation and allocation', topic: 'allitas',
      short: 'Az ügyletek összegei és adatai pontosak (ügyletállítás), illetve az egyenlegek megfelelő összegben szerepelnek, és az értékelési, felosztási korrekciókat (értékvesztés, értékcsökkenés, céltartalék) helyesen számolták el (egyenlegállítás).',
      text: '**Pontosság** (ügyletek): ár × mennyiség, árfolyam, áfa, engedmény helyes; a bizonylat és a könyvelés egyezik.\n\n**Pontosság, értékelés és felosztás** (egyenlegek):\n\n- **értékelés**: értékvesztés (vevő, készlet – nettó realizálható érték), valós érték, becslések;\n- **felosztás** (allocation): az összeg helyes megosztása időszakok vagy tételek között (pl. értékcsökkenés, aktív és passzív elhatárolás);\n- pontosság: az analitika és a főkönyv egyezik, a számítás helyes.\n\n**Tipikus eljárások**: újraszámítás, a korosított vevőlista és az utólagos befolyások vizsgálata, a fordulónap utáni eladási árak összevetése a készletértékkel, árfolyam-ellenőrzés, a becslések vizsgálata (ISA 540).',
      example: 'Készlet: a könyvvizsgáló 20 tétel bekerülési értékét a beszerzési számlákkal egyezteti (pontosság), majd a januári eladási árakat összeveti vele. 3 cikk januári eladási ára a bekerülési érték alatt van: a nettó realizálható értékre le kell értékelni (értékelés).',
      pitfall: 'A vevői megerősítő levél a létezést igen, az értékelést alig bizonyítja – a behajthatóságra az utólagos befolyások és a vevő pénzügyi helyzete adnak bizonyítékot.',
      related: ['allitasok-rendszere', 'isa-540', 'vevok-vizsgalata', 'keszletek-vizsgalata', 'celtartalek-vizsgalata'] },

    { id: 'idobeli-elhatarolas', term: 'Időbeli elhatárolás (cut-off)', en: 'cut-off', topic: 'allitas',
      short: 'Az ügyleteket és eseményeket a megfelelő időszakban rögzítették. A fordulónap körüli napokban a legnagyobb a kockázat, ezért a cut-off tesztek mindkét irányban, a fordulónap előtti és utáni ügyleteket is vizsgálják.',
      text: '**Mi a kockázat?** A decemberi árbevétel „előrehozása” (januári szállítás decemberben számlázva) vagy a decemberi költség „kitolása” januárra.\n\n**Cut-off teszt menete**:\n\n1. a leltárnál vagy a fordulónapon rögzíteni kell az utolsó kiadott és beérkezett szállítólevél sorszámát;\n2. a fordulónap előtti és utáni néhány nap (pl. ±5 munkanap) szállításait egyeztetni kell a számlázással és a könyveléssel;\n3. a fordulónap utáni jóváírások és visszáruk vizsgálata (visszavett „decemberi” eladás?).\n\nKét irány: a decemberi könyvelésből a szállítólevélre (túl korai elszámolás) és a szállítólevelekből a könyvelésre (túl késői elszámolás).',
      example: 'A december 30-i 15 M Ft-os számlához tartozó szállítólevél dátuma január 3. A teljesítés januári, így az árbevétel 2027-es: a decemberi árbevételt és vevőt 15 M Ft-tal csökkenteni kell, a készletet visszavezetni.',
      pitfall: 'A cut-off nem csak árbevételt érint: a beszerzés, a készlet és a szállítók oldalán is működik. Egy hibás cut-off egyszerre több tételt torzít (árbevétel, vevő, készlet, ELÁBÉ).',
      related: ['allitasok-rendszere', 'bekovetkezes', 'teljesseg', 'arbevetel-vizsgalata', 'isa-501', 'isa-240'] },

    { id: 'besorolas', term: 'Besorolás', en: 'classification', topic: 'allitas',
      short: 'Az ügyleteket és egyenlegeket a megfelelő számlákon és sorokon rögzítették – pl. a felújítás aktiválható és a karbantartás költség, a hosszú lejáratú hitel következő évi törlesztése rövid lejáratú.',
      text: '**Tipikus kockázatok**:\n\n- karbantartási költség aktiválása tárgyi eszközként (eredménynövelés);\n- rövid és hosszú lejáratú tételek elkülönítése (hitel, követelés);\n- működési és rendkívüli/egyéb tételek, illetve működési és finanszírozási cash-flow keverése;\n- kapcsolt féllel szembeni követelés „vevőként” kimutatása.\n\n**Eljárások**: a főkönyvi számlák tartalmának szemléje, a beruházási számlák vizsgálata (felújítás vagy javítás?), a hitelszerződések lejárati ütemezésének egyeztetése, a számlatükör és a beszámoló sorainak megfeleltetése.',
      example: 'A könyvvizsgáló az aktivált tételekből 20-at vizsgál: egy 12 M Ft-os tétel a tetőszigetelés javítása, amely nem növeli a hasznos élettartamot – költség lett volna. Besorolási (és értékelési) hiba.',
      pitfall: 'A besorolási hiba nem „ártalmatlan” azért, mert az összeg nem változik: a mutatószámok (likviditás, EBITDA) és a hitelfeltételek ezen múlhatnak.',
      related: ['allitasok-rendszere', 'bemutatas', 'targyi-eszkozok-vizsgalata'] },

    { id: 'bemutatas', term: 'Bemutatás', en: 'presentation', topic: 'allitas',
      short: 'A tételeket megfelelően összevonták vagy megbontották, világosan leírták, és a kapcsolódó közzétételek a keretrendszer szerint relevánsak és érthetők. Az ISA 315 (2019) ezt az ügyletekre és az egyenlegekre is alkalmazza.',
      text: '**Mit vizsgálunk?**\n\n- a közzétételek **teljességét** (pl. zálogjog, függő kötelezettség, kapcsolt fél ügylet, későbbi esemény);\n- az összevonás és megbontás megfelelőségét (lényeges tételek nincsenek „elrejtve”);\n- az érthetőséget és a keretrendszernek való megfelelést (közzétételi ellenőrzőlista);\n- a minőségi közzétételek összhangját a megszerzett bizonyítékokkal (pl. going concern, becslési bizonytalanság).\n\n**Eljárás**: a kiegészítő melléklet tervezetének vizsgálata ellenőrzőlistával, a közzétett adatok egyeztetése a munkapapírokkal, jegyzőkönyvek és szerződések áttekintése a hiányzó közzétételek kereséséhez.',
      example: 'A hitelszerződés szerint a gépek zálog alatt állnak, de a kiegészítő mellékletben erről nincs szó. Bemutatási hiba: a felhasználó nem tudja, hogy az eszközök nem szabadon rendelkezésre állók.',
      pitfall: 'A közzététel nem „kevésbé fontos”, mint a számok: egy hiányzó közzététel is lehet lényeges, és akár átható is (pl. going concern bizonytalanság).',
      related: ['allitasok-rendszere', 'besorolas', 'isa-570', 'isa-550', 'isa-706'] },

    { id: 'jogok-kotelezettsegek', term: 'Jogok és kötelezettségek', en: 'rights and obligations', topic: 'allitas',
      short: 'A gazdálkodó rendelkezik a kimutatott eszközök feletti jogokkal (vagy ellenőrzi azokat), és a kimutatott kötelezettségek a gazdálkodó kötelezettségei.',
      text: '**Tipikus kockázatok**: bizományba kapott készlet saját készletként; engedményezett (faktorált) vevőkövetelés; idegen tulajdonú vagy már eladott eszköz; a tulajdonos magánkötelezettsége a cég könyveiben.\n\n**Eljárások**: tulajdoni lap, adásvételi és lízingszerződés, forgalmi engedély szemléje; banki megerősítés (zálog, engedményezés); bizományosi szerződések és harmadik félnél tárolt készlet megerősítése; jegyzőkönyvek.',
      example: 'A raktárban 40 M Ft értékű áru van egy partner tulajdonában, bizományosi szerződés alapján. A leltár megszámolta, de a cégnek nincs joga felette: a készletből ki kell venni.',
      pitfall: 'A jogi tulajdon és a számviteli ellenőrzés nem mindig ugyanaz (pl. IFRS 16 szerint a lízingelt eszköz használati joga a bérlő eszköze). Mindig a keretrendszer szerinti jogot vizsgáljuk.',
      related: ['allitasok-rendszere', 'letezes', 'isa-505', 'keszletek-vizsgalata', 'targyi-eszkozok-vizsgalata'] },

    { id: 'vouching-tracing', term: 'Vouching és tracing (a vizsgálat iránya)', en: 'vouching and tracing (direction of testing)', topic: 'allitas',
      short: 'A **vouching** a könyvelt tételből indul vissza a bizonylatig (bekövetkezés, létezés), a **tracing** a forrásdokumentumból vagy a fizikai tételből indul a könyvelésig (teljesség). Az irányt a minta kiinduló halmaza dönti el.',
      visual: svgIrany, caption: 'A minta kiinduló halmaza határozza meg, melyik állítást teszteled.',
      text: '**Vouching (visszakeresés)**: könyv → bizonylat. A kérdés: „ami a könyvben van, az megtörtént/létezik?” Túlértékelés ellen.\n\n**Tracing (nyomon követés)**: bizonylat/eszköz → könyv. A kérdés: „ami megtörtént, az bekerült a könyvbe?” Alulértékelés ellen.\n\n**Példapárok**:\n\n- árbevétel-főkönyv → szállítólevél (vouching, bekövetkezés); szállítólevél → árbevétel-főkönyv (tracing, teljesség);\n- tárgyieszköz-nyilvántartás → gép a csarnokban (létezés); gép a csarnokban → nyilvántartás (teljesség);\n- leltárlista → polc (létezés); polc → leltárlista (teljesség);\n- januári kifizetés → decemberi szállítói kötelezettség (teljesség).',
      example: 'A könyvvizsgáló két mintát vesz: 25 tételt a decemberi árbevétel-főkönyvből (vouching) és 25 sorszámot a szállítólevél-tömbből (tracing). Az első fiktív, a második kimaradt bevételt keres.',
      pitfall: 'A vouching nem „rosszabb”, csak másra jó: aki teljességet a könyvelt tételekből próbál tesztelni, a hiányzó tételt sosem találja meg, mert az nincs a mintavételi sokaságban.',
      related: ['bekovetkezes', 'letezes', 'teljesseg', 'isa-501', 'isa-530', 'eljaras-allitas-matrix'],
      widget: { type: 'audit-vouching' } },

    { id: 'eljaras-allitas-matrix', term: 'Eljárás ↔ állítás megfeleltetés mérlegtételenként', en: 'audit procedures mapped to assertions by account', topic: 'allitas',
      short: 'Minden mérlegtételnél és ügylettípusnál meg kell határozni a releváns állításokat, és mindegyikhez olyan eljárást kell rendelni, amely arra valóban bizonyítékot ad. A kereszttábla megmutatja, melyik eljárás melyik állítást teszteli.',
      text: '**Az elv**: egy eljárás általában egy-két állításra ad erős bizonyítékot, másokra gyengét vagy semmit. A könyvvizsgálati programot ezért állításonként kell lefedni.\n\n**Gyors összefoglaló**:\n\n- **külső megerősítés** → létezés, jogok (bank: teljesség is); gyengén értékelés;\n- **fizikai szemle, leltár** → létezés (és a polcról a listába: teljesség); az állapot alapján részben értékelés;\n- **vouching** → bekövetkezés, létezés; **tracing** → teljesség;\n- **cut-off teszt** → időbeli elhatárolás;\n- **újraszámítás** → pontosság, értékelés és felosztás;\n- **utólagos befolyások, fordulónap utáni eladások** → értékelés (és létezés);\n- **el nem számolt kötelezettségek keresése** → teljesség;\n- **szerződések, tulajdoni lap** → jogok és kötelezettségek;\n- **közzétételi ellenőrzőlista** → bemutatás;\n- **elemző eljárás** → több állítás, de jellemzően teljesség és pontosság.\n\nVálassz egy mérlegtételt a táblázatban!',
      example: 'Pénzeszközök: banki megerősítés (létezés, teljesség, jogok), bankegyeztetés újraszámítása (pontosság), devizaárfolyam ellenőrzése (értékelés), zárolt betét közzététele (bemutatás).',
      pitfall: 'A program nem eljárások listája, hanem **állítások lefedése**: ha egy releváns állításhoz nincs eljárás (pl. a vevők értékeléséhez), a bizonyíték hiányos, akárhány megerősítő levél ment ki.',
      related: ['allitasok-rendszere', 'vouching-tracing', 'penzeszkozok-vizsgalata', 'vevok-vizsgalata', 'keszletek-vizsgalata', 'targyi-eszkozok-vizsgalata', 'szallitok-vizsgalata', 'celtartalek-vizsgalata', 'arbevetel-vizsgalata', 'isa-330'],
      widget: { type: 'audit-matrix' } },

    { id: 'penzeszkozok-vizsgalata', term: 'Pénzeszközök vizsgálata', en: 'auditing cash and bank balances', topic: 'allitas',
      short: 'A pénzeszközök vizsgálatának gerince a banki megerősítés (minden számlára, nulla egyenlegűre is) és a bankegyeztetés újraszámítása; a készpénznél a pénztár meglepetésszerű ellenőrzése.',
      text: '**Releváns állítások és eljárások**:\n\n- **létezés, jogok**: banki megerősítő levél (egyenlegek, zálog, garancia, aláírási jogok);\n- **teljesség**: a bank minden számlát felsorol – a nem könyvelt számla is kiderül; nulla egyenlegű és év közben megszüntetett számlákra is kell levél;\n- **pontosság**: a bankegyeztetés újraszámítása, az úton lévő tételek követése a januári kivonaton;\n- **értékelés**: devizaszámlák átszámítása a fordulónapi árfolyamon;\n- **időbeli elhatárolás**: a fordulónap körüli átvezetések (ún. kiting – pénz „kétszer” két számlán);\n- **bemutatás**: zárolt, óvadéki betét elkülönítése, pénzeszköz-egyenértékesek.',
      example: 'A banki megerősítés szerint a cégnek van egy 200 000 EUR-s óvadéki betétje, amelyet a pénzeszközök között mutattak ki. Ez nem szabadon felhasználható: elkülönítve, közzététellel kell bemutatni.',
      pitfall: 'A „kis tétel, alacsony kockázat” gondolat a pénzeszközöknél félrevezet: a csalás (sikkasztás) gyakran itt kezdődik, és a banki megerősítés olcsó, erős bizonyíték.',
      related: ['eljaras-allitas-matrix', 'isa-505', 'letezes', 'teljesseg'] },

    { id: 'vevok-vizsgalata', term: 'Vevőkövetelések vizsgálata', en: 'auditing trade receivables', topic: 'allitas',
      short: 'A vevőknél a létezés (megerősítő levél, utólagos befolyások) és az értékelés (korosítás, értékvesztés, behajthatóság) a kulcs; az időbeli elhatárolás az árbevétel cut-off tesztjével függ össze.',
      text: '**Releváns állítások és eljárások**:\n\n- **létezés**: pozitív megerősítő levél; nem válaszolóknál utólagos befolyás és szállítólevél;\n- **jogok**: faktorálás, engedményezés (szerződések, banki megerősítés);\n- **értékelés**: a korosított lista teljességének és pontosságának tesztelése, utólagos befolyások, vitatott tételek, a vevő pénzügyi helyzete, értékvesztés-számítás újraszámítása;\n- **időbeli elhatárolás**: fordulónap körüli számlák és szállítólevelek;\n- **teljesség**: az analitika és a főkönyv egyeztetése, szállítólevelekből kiinduló tracing;\n- **bemutatás**: kapcsolt felekkel szembeni követelések elkülönítése, hosszú lejáratú rész.',
      example: 'A korosított lista szerint 18 M Ft 180 napon túli. A januári–februári befolyás ebből 2 M Ft; a vevők közül kettő felszámolás alatt áll. A könyvvizsgáló 14 M Ft értékvesztést tart szükségesnek a vezetés 5 M Ft-jával szemben: 9 M Ft megítélésen alapuló hiba.',
      pitfall: 'A megerősítő levélre adott egyező válasz nem bizonyítja, hogy a vevő fizetni is fog: az értékelést külön kell tesztelni.',
      related: ['eljaras-allitas-matrix', 'isa-505', 'pontossag-ertekeles', 'arbevetel-vizsgalata', 'isa-540'] },

    { id: 'arbevetel-vizsgalata', term: 'Árbevétel vizsgálata', en: 'auditing revenue', topic: 'allitas',
      short: 'Az árbevétel az ISA 240 szerint feltételezett csalási kockázat. A bekövetkezést (vouching), a teljességet (tracing), az időbeli elhatárolást (cut-off) és a pontosságot (árak, engedmények) külön eljárások tesztelik.',
      text: '**Releváns állítások és eljárások**:\n\n- **bekövetkezés**: könyvelt számlák → aláírt szállítólevél, vevői megrendelés, befolyás;\n- **teljesség**: szállítólevelek sorszám-folytonossága → számla → főkönyv; elemző eljárás (mennyiség × ár, havi trend);\n- **pontosság**: árlista, szerződéses ár, engedmények és bónuszok újraszámítása;\n- **időbeli elhatárolás**: cut-off a fordulónap körül, január eleji jóváírások és visszáruk;\n- **besorolás**: árbevétel vagy egyéb bevétel, bruttó vagy nettó (ügynöki) elszámolás;\n- **bemutatás**: az árbevétel bontása és a számviteli politika közzététele (IFRS 15).',
      example: 'Havi árbevétel-elemzés: decemberben 40%-kal nő a forgalom egyetlen vevőnél, januárban ugyanennek a vevőnek nagy jóváírást adnak. Ez a „csatornatöltés” (channel stuffing) jele – cut-off és bekövetkezés teszt kell.',
      pitfall: 'Az árbevétel-elszámolás csalási kockázatának feltételezése megdönthető, de csak indokolt esetben (pl. egyszerű, egyetlen bérleti díjbevétel) – és ezt dokumentálni kell.',
      related: ['eljaras-allitas-matrix', 'bekovetkezes', 'idobeli-elhatarolas', 'isa-240', 'vevok-vizsgalata'] },

    { id: 'keszletek-vizsgalata', term: 'Készletek vizsgálata', en: 'auditing inventories', topic: 'allitas',
      short: 'A készleteknél a leltár megfigyelése (létezés, teljesség), a bekerülési érték és a nettó realizálható érték vizsgálata (értékelés), a cut-off és a harmadik félnél lévő vagy idegen készlet (jogok) a fő terület.',
      text: '**Releváns állítások és eljárások**:\n\n- **létezés**: jelenlét a leltáron, próbaszámlálás a listáról a polcra; harmadik félnél tárolt készletre megerősítés;\n- **teljesség**: próbaszámlálás a polcról a listára; a leltár és a főkönyv egyeztetése;\n- **jogok**: bizományba kapott és vevőnek már eladott, de még raktárban lévő áru elkülönítése;\n- **értékelés**: bekerülési érték (beszerzési számlák, önköltség-számítás, általános költségek felosztása normál kapacitással), nettó realizálható érték (fordulónap utáni eladási árak), lassú forgású és elavult tételek;\n- **időbeli elhatárolás**: az utolsó szállítólevél-sorszámok a leltárnál;\n- **bemutatás**: zálog, készletértékelési módszer közzététele.',
      example: 'A leltáron a könyvvizsgáló észreveszi, hogy egy sarokban poros, sérült dobozok állnak; a listán teljes értéken szerepelnek. Megjelöli őket, és a fordulónap utáni eladások alapján 6 M Ft leértékelést kezdeményez.',
      pitfall: 'A „megszámoltuk, tehát rendben van” csak a létezést zárja le – az értékelés (elavulás, NRV) és a jogok (idegen készlet) külön kérdés.',
      related: ['eljaras-allitas-matrix', 'isa-501', 'jogok-kotelezettsegek', 'pontossag-ertekeles', 'idobeli-elhatarolas'] },

    { id: 'targyi-eszkozok-vizsgalata', term: 'Tárgyi eszközök vizsgálata', en: 'auditing property, plant and equipment', topic: 'allitas',
      short: 'A tárgyi eszközöknél az év közbeni növekedések (vouching a számlákig, aktiválhatóság), a selejtezések, az értékcsökkenés újraszámítása, a tulajdonjog és az értékvesztésre utaló jelek a fő eljárások.',
      text: '**Releváns állítások és eljárások**:\n\n- **létezés**: a nyilvántartásból a fizikai eszközig (szemle); selejtezési jegyzőkönyvek;\n- **teljesség**: a fizikai eszköztől a nyilvántartásig; a javítás-karbantartás számla átnézése (nem aktivált beruházás?);\n- **jogok**: tulajdoni lap, adásvételi szerződés, forgalmi engedély; zálogjog a banki megerősítésből;\n- **pontosság, értékelés**: a növekedések számlákkal egyeztetése, az értékcsökkenés újraszámítása, a hasznos élettartam észszerűsége, értékvesztési jelek;\n- **besorolás**: felújítás vagy karbantartás;\n- **bemutatás**: eszközmozgás-tábla (nyitó + növekedés − csökkenés = záró).',
      example: 'Az értékcsökkenés elemző tesztje: átlagos bruttó érték 900 M Ft × 10% átlagos kulcs = 90 M Ft elvárás; könyvelt 72 M Ft. A különbség oka: három gép aktiválása elmaradt, az értékcsökkenésük nem indult el.',
      pitfall: 'Az előző évi tárgyieszköz-állomány nem kell, hogy minden évben teljesen újra vizsgálva legyen – de a növekedések és csökkenések igen, és a teljes állomány értékvesztési jeleit minden évben mérlegelni kell.',
      related: ['eljaras-allitas-matrix', 'letezes', 'besorolas', 'jogok-kotelezettsegek', 'isa-520'] },

    { id: 'szallitok-vizsgalata', term: 'Szállítói kötelezettségek vizsgálata', en: 'auditing trade payables', topic: 'allitas',
      short: 'A szállítóknál a fő kockázat az alulértékelés, ezért a teljesség a kulcsállítás: el nem számolt kötelezettségek keresése a fordulónap utáni kifizetésekből és beérkező számlákból, szállítói egyenlegközlők a nagy forgalmú szállítóknak.',
      text: '**Releváns állítások és eljárások**:\n\n- **teljesség**: el nem számolt kötelezettségek keresése (januári–februári kifizetések, beérkezett számlák, nyitott megrendelések), szállítói egyenlegközlő vagy a szállító saját kivonatának egyeztetése, áruátvételi jegyek decemberi tételeinek tracingje;\n- **létezés, kötelezettség**: kisebb kockázat, de a fiktív szállító (csalás) ellen a törzsadat-változások vizsgálata;\n- **időbeli elhatárolás**: a fordulónap körüli áruátvételek;\n- **pontosság**: devizás szállítók átszámítása;\n- **bemutatás**: kapcsolt felekkel szembeni kötelezettségek elkülönítése.',
      example: 'A szállítói analitikában egy fő alapanyag-szállító egyenlege nulla, pedig éves forgalma 600 M Ft. A szállító kivonata szerint 45 M Ft decemberi számla nyitott – a cég „elfelejtette” lekönyvelni.',
      pitfall: 'A szállítói megerősítést nem a legnagyobb egyenlegek alapján kell választani, és a nulla egyenleg nem jelent alacsony kockázatot – teljességi szempontból épp fordítva.',
      related: ['eljaras-allitas-matrix', 'teljesseg', 'idobeli-elhatarolas', 'vouching-tracing'] },

    { id: 'celtartalek-vizsgalata', term: 'Céltartalékok és függő kötelezettségek vizsgálata', en: 'auditing provisions and contingent liabilities', topic: 'allitas',
      short: 'A céltartalékoknál a teljesség (ki nem mutatott kötelem) és az értékelés (a legjobb becslés) a kulcs; bizonyíték: jogi levelezés, ügyvédi megkeresés, jegyzőkönyvek, garanciális statisztikák, későbbi események.',
      text: '**Releváns állítások és eljárások**:\n\n- **teljesség**: jegyzőkönyvek, szerződések, jogi költségszámlák, ügyvédi megkeresés (ISA 501), hatósági levelezés átnézése; későbbi események vizsgálata;\n- **létezés, kötelezettség**: van-e jelen kötelem múltbeli esemény alapján (nem csak szándék);\n- **értékelés**: a becslés módszere, feltevései, a múltbeli adatok (garancia), visszatekintő vizsgálat (ISA 540), diszkontálás;\n- **bemutatás**: függő kötelezettségek közzététele, ha a kiáramlás nem valószínű, de nem is távoli.',
      example: 'Az ügyvédi levél szerint egy kártérítési perben „valószínű” a marasztalás 30–40 M Ft-ban, de a cég nem képzett céltartalékot. A könyvvizsgáló legalább 30 M Ft-os hibát állapít meg, és értékeli a közzétételt.',
      pitfall: 'A vezetés „nem akarunk céltartalékot, mert akkor elismerjük a felelősséget” érve nem számviteli érv: a keretrendszer szerinti valószínűség dönt, a közzététel szövege pedig óvatosan is megfogalmazható.',
      related: ['eljaras-allitas-matrix', 'teljesseg', 'pontossag-ertekeles', 'isa-501', 'isa-540', 'isa-560'] }
  ];

